import{_ as o,c as t,o as a,ae as n}from"./chunks/framework.2MVDia4S.js";const h=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"guide/introduction.md","filePath":"guide/introduction.md"}'),r={name:"guide/introduction.md"};function i(c,e,d,l,s,p){return a(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p>EthBFT is a thin BFT consensus adapter for Ethereum Execution Layer clients. CometBFT decides complete Ethereum execution payloads, and every validator asks an independent Geth node to validate the same state transition.</p><blockquote><p><strong>Status:</strong> v0.1.0 MVP. The default Docker network has one validator. The protocol path is designed for one dedicated EL per CometBFT validator, but the project is not yet a production multi-validator network.</p></blockquote><h2 id="current-protocol" tabindex="-1">Current protocol <a class="header-anchor" href="#current-protocol" aria-label="Permalink to &quot;Current protocol&quot;">​</a></h2><ul><li>The proposer builds an Engine API V2 execution payload in <code>PrepareProposal</code>.</li><li>A canonical RLP envelope and the exact ordered payload transactions become the CometBFT proposal.</li><li>Validators reconstruct the payload and require <code>engine_newPayloadV2</code> to return <code>VALID</code> in <code>ProcessProposal</code>.</li><li>Only after CometBFT decides the proposal does EthBFT advance canonical EL forkchoice.</li><li>The ABCI app hash commits to the EL block hash, state root, receipts root, and transaction root.</li><li><code>Commit</code> persists the CometBFT height to EL block mapping with an fsynced atomic state update.</li></ul><h2 id="mvp-boundary" tabindex="-1">MVP boundary <a class="header-anchor" href="#mvp-boundary" aria-label="Permalink to &quot;MVP boundary&quot;">​</a></h2><p>Protocol v1 supports a Shanghai-only private execution chain, Engine API V2, empty withdrawals, and non-blob Ethereum transactions. State sync, dynamic validators, mixed execution clients, and external light-client proofs remain future work.</p><p>See <a href="/ethbft/rfc/0001-execution-payload-consensus.html">RFC 0001</a> for the complete target protocol and security model.</p>',8)])])}const m=o(r,[["render",i]]);export{h as __pageData,m as default};
